// This file is generated by AI.

// 选项卡关闭的统一入口。
//
// 不同种类的选项卡关闭前要做的事不同 (未保存确认、未完成配音任务确认、清理
// Monaco model / 预处理器会话 / 配音卡), 但都必须走同一条路径, 否则容易出现
// "关掉了 DOM 却留下状态"这类不一致。这里集中处理。

import { requestConfirm } from '../confirm';
import { disposeModel } from '../lsp/monaco';
import { disposeNovelTab } from '../novel/registry';
import { useAppStore } from '../state/store';
import { WORKBENCH_TAB_ID, type WorkbenchTabItem } from './model';
import { confirmClose } from '../unsaved';
import { closeVoiceWorkbench } from '../voice/mode';
import { voiceController } from '../voice/controller';

/** 关闭选项卡; 需要确认时先弹窗, 用户取消则什么都不做 */
export function requestCloseTab(tab: WorkbenchTabItem): void {
  const store = useAppStore.getState();

  if (tab.kind === 'scene') {
    const close = () =>
      confirmClose(() => {
        // 撤下这个场景未完成的任务再销毁卡片: 卡片没了以后任务完成也没地方回填
        voiceController.abandonCard(tab.path);
        disposeModel(tab.path);
        useAppStore.getState().closeDocument(tab.path);
        useAppStore.getState().closeTab(tab.id);
      }, tab.path);

    const count = voiceController.unfinishedCount(tab.path);
    if (count > 0) {
      requestConfirm({
        title: '这个场景还有配音任务',
        description: `还有 ${count} 个任务没跑完。关闭选项卡会取消它们（已经生成出来的记录不受影响），也可以先在配音工作台里等它们跑完。`,
        confirmLabel: '关闭并取消',
        danger: true,
        action: close,
      });
      return;
    }
    close();
    return;
  }

  if (tab.kind === 'novel') {
    disposeNovelTab(tab.id);
    store.closeTab(tab.id);
    return;
  }

  if (tab.id === WORKBENCH_TAB_ID) {
    // 工作台是配音功能的开关: 关闭时确认未完成任务、撤下它们, 并顺手停掉 GSOV 服务
    // (确认与收尾都在 `closeVoiceWorkbench` 里, 顶部按钮走的是同一个入口)
    closeVoiceWorkbench();
    return;
  }

  store.closeTab(tab.id);
}

/** 激活选项卡 (供外部跳转使用) */
export function activateTab(id: string): void {
  useAppStore.getState().activateTab(id);
}
